-- Correct buyer rankings without rewriting or deleting any warehouse row.
--
-- buyerDB's stored norm_name is generated by sbi_norm_entity(). That legacy
-- function removes legal designators anywhere in a name and does not trim the
-- result. Consequently, suffix and suffix-free forms can occupy separate
-- entity rows (for example, "139 Bowery Holdings" and
-- "139 BOWERY HOLDINGS LLC"). Conversely, a leading "LP" can be meaningful,
-- so blindly trimming the existing norm_name would create false matches such
-- as "LP 208 FLATBUSH LLC" and "208 FLATBUSH LLC".
--
-- This migration is deliberately read-contract-only:
--   * no sbi_* table row is inserted, updated, merged, or deleted;
--   * existing entity UUIDs, contacts, provenance, and party links survive;
--   * a new query-only key removes terminal legal suffixes, but preserves a
--     leading LP and all other non-terminal tokens;
--   * api_buyers aggregates distinct deal IDs across proven aliases; and
--   * api_entity returns the complete address-linked history for every member
--     of the requested entity's canonical group.

do $migration$
begin
  if to_regclass('public.sbi_entities') is null
     or to_regclass('public.sbi_deal_parties') is null
     or to_regclass('public.sbi_deals') is null
     or to_regclass('public.sbi_properties') is null
     or to_regclass('public.sbi_contacts') is null then
    raise notice 'buyer intelligence warehouse is absent; canonical identity migration skipped';
    return;
  end if;

  execute $ddl$
    create or replace function public.sbi_canonical_entity_key(v text)
    returns text
    language sql
    immutable
    parallel safe
    set search_path = pg_catalog
    as $function$
      select nullif(
        btrim(
          regexp_replace(
            btrim(
              regexp_replace(
                replace(upper(coalesce(v, '')), '.', ''),
                '[^A-Z0-9]+',
                ' ',
                'g'
              )
            ),
            '([[:space:]]+(LLC|INC|CORP|CORPORATION|LP|LTD|COMPANY|CO))+$',
            '',
            'g'
          )
        ),
        ''
      )
    $function$
  $ddl$;

  execute $ddl$
    create or replace function public.api_buyers(
      borough text default null,
      asset_type text default null,
      price_min numeric default null,
      price_max numeric default null,
      date_min date default null,
      min_deals integer default 1,
      rank_by text default 'count',
      lim integer default 60
    )
    returns jsonb
    language sql
    stable
    security definer
    set search_path = public
    as $function$
      with keyed_entities as (
        select
          e.entity_id,
          e.display_name,
          e.is_spv_suspect,
          public.sbi_canonical_entity_key(e.display_name) as canonical_key
        from public.sbi_entities e
      ),
      filtered_deals as (
        select distinct
          ke.canonical_key,
          d.deal_id,
          d.sale_price,
          d.sale_date,
          d.asset_type,
          p.borough
        from keyed_entities ke
        join public.sbi_deal_parties dp
          on dp.entity_id = ke.entity_id
         and dp.role = 'buyer'
        join public.sbi_deals d on d.deal_id = dp.deal_id
        join public.sbi_properties p on p.property_id = d.property_id
        where ke.canonical_key is not null
          and (api_buyers.borough is null or api_buyers.borough = '' or p.borough = api_buyers.borough)
          and (api_buyers.asset_type is null or api_buyers.asset_type = '' or d.asset_type = api_buyers.asset_type)
          and (api_buyers.price_min is null or d.sale_price >= api_buyers.price_min)
          and (api_buyers.price_max is null or d.sale_price <= api_buyers.price_max)
          and (api_buyers.date_min is null or d.sale_date >= api_buyers.date_min)
      ),
      matching_keys as (
        select distinct canonical_key from filtered_deals
      ),
      representatives as (
        select
          ke.canonical_key,
          (array_agg(
            ke.entity_id
            order by length(ke.display_name), lower(ke.display_name), ke.display_name, ke.entity_id
          ))[1] as entity_id,
          (array_agg(
            ke.display_name
            order by length(ke.display_name), lower(ke.display_name), ke.display_name, ke.entity_id
          ))[1] as name,
          bool_or(ke.is_spv_suspect) as is_spv_suspect
        from keyed_entities ke
        join matching_keys mk using (canonical_key)
        group by ke.canonical_key
      ),
      deal_aggregates as (
        select
          fd.canonical_key,
          count(*) as n,
          coalesce(sum(fd.sale_price), 0) as vol,
          max(fd.sale_date) as last_deal,
          min(fd.sale_price) as min_price,
          max(fd.sale_price) as max_price,
          array_agg(distinct fd.asset_type order by fd.asset_type)
            filter (where fd.asset_type is not null) as types,
          array_agg(distinct fd.borough order by fd.borough)
            filter (where fd.borough is not null) as boroughs
        from filtered_deals fd
        group by fd.canonical_key
        having count(*) >= greatest(api_buyers.min_deals, 1)
      ),
      grouped as (
        select
          r.entity_id,
          r.name,
          r.is_spv_suspect,
          da.n,
          da.vol,
          da.last_deal,
          da.min_price,
          da.max_price,
          da.types,
          da.boroughs,
          exists (
            select 1
            from keyed_entities member
            join public.sbi_contacts c on c.entity_id = member.entity_id
            where member.canonical_key = da.canonical_key
              and (c.phone is not null or c.email is not null)
          ) as has_contact
        from deal_aggregates da
        join representatives r using (canonical_key)
      ),
      ranked as (
        select *
        from grouped
        order by
          case when api_buyers.rank_by in ('vol', 'volume') then vol end desc nulls last,
          case when api_buyers.rank_by not in ('vol', 'volume') then n end desc nulls last,
          case when api_buyers.rank_by in ('vol', 'volume') then n else vol end desc nulls last,
          last_deal desc nulls last,
          lower(name),
          entity_id
        limit least(greatest(api_buyers.lim, 1), 200)
      )
      select jsonb_build_object(
        'buyers',
        coalesce((select jsonb_agg(to_jsonb(ranked)) from ranked), '[]'::jsonb)
      )
    $function$
  $ddl$;

  execute $ddl$
    create or replace function public.api_entity(eid uuid)
    returns jsonb
    language sql
    stable
    security definer
    set search_path = public
    as $function$
      with target as (
        select
          e.*,
          public.sbi_canonical_entity_key(e.display_name) as canonical_key
        from public.sbi_entities e
        where e.entity_id = api_entity.eid
      ),
      group_entities as (
        select e.entity_id
        from public.sbi_entities e
        join target t
          on public.sbi_canonical_entity_key(e.display_name) = t.canonical_key
      ),
      deal_rows as (
        select distinct on (dp.deal_id, dp.role)
          dp.deal_id,
          dp.role,
          d.sale_date,
          p.address_raw as address,
          p.borough,
          d.asset_type,
          d.sale_price,
          d.source_url
        from group_entities ge
        join public.sbi_deal_parties dp on dp.entity_id = ge.entity_id
        join public.sbi_deals d on d.deal_id = dp.deal_id
        join public.sbi_properties p on p.property_id = d.property_id
        order by dp.deal_id, dp.role, dp.created_at, ge.entity_id
      )
      select case
        when not exists (select 1 from target) then jsonb_build_object('error', 'not found')
        else jsonb_build_object(
          'entity', (
            select
              (to_jsonb(t) - 'canonical_key') ||
              jsonb_build_object(
                'canonical_entity_ids',
                coalesce(
                  (select jsonb_agg(ge.entity_id order by ge.entity_id) from group_entities ge),
                  '[]'::jsonb
                )
              )
            from target t
          ),
          'deals', coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'deal_id', dr.deal_id,
                  'role', dr.role,
                  'sale_date', dr.sale_date,
                  'address', dr.address,
                  'borough', dr.borough,
                  'asset_type', dr.asset_type,
                  'sale_price', dr.sale_price,
                  'source_url', dr.source_url
                )
                order by dr.sale_date desc nulls last, dr.deal_id, dr.role
              )
              from deal_rows dr
            ),
            '[]'::jsonb
          ),
          'contacts', coalesce(
            (
              select jsonb_agg(
                to_jsonb(c)
                order by c.is_primary desc, c.created_at, c.contact_id
              )
              from group_entities ge
              join public.sbi_contacts c on c.entity_id = ge.entity_id
            ),
            '[]'::jsonb
          )
        )
      end
    $function$
  $ddl$;

  execute $ddl$
    create or replace function public.buyer_intelligence_schema_check()
    returns jsonb
    language plpgsql
    stable
    security definer
    set search_path = public, pg_catalog
    as $function$
    declare
      manhattan_buyer_deals bigint := 0;
      missing_property_addresses bigint := 0;
      raw_repeat_buyers bigint := 0;
      canonical_repeat_buyers bigint := 0;
      canonical_alias_groups bigint := 0;
      acl_ok boolean := false;
    begin
      select
        count(distinct dp.deal_id),
        count(distinct dp.deal_id) filter (
          where p.address_raw is null or btrim(p.address_raw) = ''
        )
      into manhattan_buyer_deals, missing_property_addresses
      from public.sbi_deal_parties dp
      join public.sbi_deals d on d.deal_id = dp.deal_id
      join public.sbi_properties p on p.property_id = d.property_id
      where dp.role = 'buyer' and p.borough = 'Manhattan';

      select count(*) into raw_repeat_buyers
      from (
        select dp.entity_id
        from public.sbi_deal_parties dp
        join public.sbi_deals d on d.deal_id = dp.deal_id
        join public.sbi_properties p on p.property_id = d.property_id
        where dp.role = 'buyer' and p.borough = 'Manhattan'
        group by dp.entity_id
        having count(distinct dp.deal_id) >= 2
      ) raw_groups;

      select count(*) into canonical_repeat_buyers
      from (
        select public.sbi_canonical_entity_key(e.display_name) as canonical_key
        from public.sbi_deal_parties dp
        join public.sbi_entities e on e.entity_id = dp.entity_id
        join public.sbi_deals d on d.deal_id = dp.deal_id
        join public.sbi_properties p on p.property_id = d.property_id
        where dp.role = 'buyer' and p.borough = 'Manhattan'
        group by public.sbi_canonical_entity_key(e.display_name)
        having count(distinct dp.deal_id) >= 2
      ) canonical_groups;

      select count(*) into canonical_alias_groups
      from (
        select public.sbi_canonical_entity_key(e.display_name)
        from public.sbi_entities e
        group by public.sbi_canonical_entity_key(e.display_name)
        having count(*) > 1
      ) aliases;

      acl_ok :=
        coalesce(has_function_privilege('service_role', 'public.api_buyers(text,text,numeric,numeric,date,integer,text,integer)', 'execute'), false) and
        coalesce(has_function_privilege('service_role', 'public.api_entity(uuid)', 'execute'), false) and
        not coalesce(has_function_privilege('anon', 'public.api_buyers(text,text,numeric,numeric,date,integer,text,integer)', 'execute'), true) and
        not coalesce(has_function_privilege('authenticated', 'public.api_buyers(text,text,numeric,numeric,date,integer,text,integer)', 'execute'), true) and
        not coalesce(has_function_privilege('anon', 'public.api_entity(uuid)', 'execute'), true) and
        not coalesce(has_function_privilege('authenticated', 'public.api_entity(uuid)', 'execute'), true);

      return jsonb_build_object(
        'ok', missing_property_addresses = 0 and canonical_repeat_buyers >= raw_repeat_buyers and acl_ok,
        'revision', '202608190002_canonical_identity',
        'manhattanBuyerDeals', manhattan_buyer_deals,
        'missingPropertyAddresses', missing_property_addresses,
        'rawRepeatBuyers', raw_repeat_buyers,
        'canonicalRepeatBuyers', canonical_repeat_buyers,
        'canonicalAliasGroups', canonical_alias_groups,
        'serviceRoleOnly', acl_ok
      );
    end
    $function$
  $ddl$;

  execute 'revoke all on function public.sbi_canonical_entity_key(text) from public, anon, authenticated';
  execute 'revoke all on function public.api_buyers(text,text,numeric,numeric,date,integer,text,integer) from public, anon, authenticated';
  execute 'revoke all on function public.api_entity(uuid) from public, anon, authenticated';
  execute 'revoke all on function public.buyer_intelligence_schema_check() from public, anon, authenticated';

  execute 'grant execute on function public.sbi_canonical_entity_key(text) to service_role';
  execute 'grant execute on function public.api_buyers(text,text,numeric,numeric,date,integer,text,integer) to service_role';
  execute 'grant execute on function public.api_entity(uuid) to service_role';
  execute 'grant execute on function public.buyer_intelligence_schema_check() to service_role';
end
$migration$;
